def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=3: continue
            # A marker generates an upward-facing five-cell cap, a three-cell
            # centered neck, and a horizontal baseline reaching the nearest
            # left/right grid edge with a five-cell 8-colored center.
            for dc in range(-2,3):
                if 0<=r-2<h and 0<=c+dc<w: out[r-2][c+dc]=5
            if 0<=r-1<h and 0<=c<w: out[r-1][c]=5
            for dr in (-1,0,1,2):
                if 0<=r+dr<h:
                    for dc in (-2,2):
                        if 0<=c+dc<w: out[r+dr][c+dc]=2
            if 0<=r+2<h:
                out[r+2]=[2]*w
                for x in range(max(0,c-2),min(w,c+3)):
                    out[r+2][x]=8
    return out

